package com.example

/**
 * Curated, 100% syllabus-aligned, distinct Flashcards for Buddhism (බුද්ධ ධර්මය).
 * Part 2: Categories 11 to 20 (20 distinct questions per category).
 * Strictly guarantees no repeated questions within the same category or across different categories.
 */
object FlashcardBankBuddhismSetsPart2 {

  fun getCard(setNum: Int, cardNum: Int): CardContentTuple {
    val c = cardNum.coerceIn(1, 20)
    return when (setNum) {
      11 -> set11[(c - 1) % set11.size]
      12 -> set12[(c - 1) % set12.size]
      13 -> set13[(c - 1) % set13.size]
      14 -> set14[(c - 1) % set14.size]
      15 -> set15[(c - 1) % set15.size]
      16 -> set16[(c - 1) % set16.size]
      17 -> set17[(c - 1) % set17.size]
      18 -> set18[(c - 1) % set18.size]
      19 -> set19[(c - 1) % set19.size]
      20 -> set20[(c - 1) % set20.size]
      else -> set11[(c - 1) % set11.size]
    }
  }

  // --- SET 11: ත්‍රිලක්ෂණය (අනිච්ච, දුක්ඛ, අනත්ත) ---
  private val set11 = listOf(
    CardContentTuple("ත්‍රිලක්ෂණය යනු කුමක්ද?", "ලෝකයේ සියලු හේතූන්ගෙන් හටගත් (සංඛත) ධර්මයන්හි පවතින පොදු ලක්ෂණ 3යි: අනිත්‍ය (අනිච්ච), දුක්ඛ (දුක්ඛ), අනාත්ම (අනත්ත).", "සබ්බේ සංඛාරා අනිච්චා, සබ්බේ සංඛාරා දුක්ඛා, සබ්බේ ධම්මා අනත්තා.", "ත්‍රිලක්ෂණය"),
    CardContentTuple("\"සබ්බේ සංඛාරා අනිච්චා\" යන්නෙහි අර්ථය කුමක්ද?", "හේතූන්ගෙන් හටගත් සියලු රූප, වේදනා ආදී සංස්කාර ධර්මයෝ නැසෙන, විනාශ වන, වෙනස් වන සුළුය (අනිත්‍යය).", "උප්පාද (ඉපදීම), ඨිති (පැවතීම), භංග (නැතිවීම) ලක්ෂණ ඇත.", "අනිත්‍ය ලක්ෂණය"),
